def seg(time: str, role: str, text: str) -> dict[str, str]:
    return {"time": time, "role": role, "text": text}


def frame(n: int, kind: str, dur: str, visual: str, overlay: str) -> dict[str, Any]:
    return {"n": n, "kind": kind, "duration": dur, "visual": visual, "overlay": overlay}


def standard_storyboard(hook: str, point1: str, point2: str, point3: str, conclusion: str, broll1: str, broll2: str, cta: str = CTA) -> list[dict[str, Any]]:
    return [
        frame(1, "HOOK COVER", "1.5 сек", "Очень крупный план, прямой взгляд", hook.upper()),
        frame(2, "A-ROLL", "3 сек", "Крупный план, фраза без приветствия", hook),
        frame(3, "B-ROLL", "2 сек", broll1, point1),
        frame(4, "A-ROLL", "3 сек", "Средний план, пункт 1", point1),
        frame(5, "B-ROLL", "2 сек", broll2, point2),
        frame(6, "A-ROLL", "3 сек", "Новый угол, пункт 2", point2),
        frame(7, "B-ROLL", "2 сек", "Крупная деталь / метафора", point3),
        frame(8, "A-ROLL", "3 сек", "Статичный финальный кадр", conclusion),
        frame(9, "CTA", "3 сек", "Мягкий тёмный фон", cta),
    ]


def script_segments(lines: list[tuple[str, str, str]]) -> list[dict[str, str]]:
    return [seg(*line) for line in lines]


