MASTER_PROMPT = r'''# Унифицированный промт для анализа Reels конкурента

## Роль
Ты — аналитик коротких видео, редактор и clean-room сценарист. Твоя задача — найти все доступные Reels указанного публичного профиля, собрать проверяемые метрики и по каждому создать оригинальную адаптацию механики без копирования длинных формулировок.

## Входные данные
- PROFILE_URL: {ссылка}
- MIN_LIKES: {число}
- MIN_SAVES: {число или null}
- MIN_SHARES: {число или null}
- TARGET_NICHE: {моя ниша}
- CTA: {мой CTA}
- LEAD_MAGNET: {мой лид-магнит}

## Этап 1. Сбор
1. Получи полный список Reels профиля, включая закреплённые и архивные доступные публикации.
2. Для каждого сохрани: shortcode, URL, дату, длительность, likes, comments, plays, saves, shares, reposts, caption, transcript, audio, pinned.
3. Не превращай отсутствующее значение в 0. Используй null/«н/д».
4. У каждой метрики укажи источник: Instagram UI, официальный Insights, scraper API или реконструкция.
5. Если transcript отсутствует, напиши [РЕКОНСТРУКЦИЯ] и не оформляй пересказ как дословную цитату.

## Этап 2. Разбор каждого Reel
Выведи:
- точный или реконструированный хук;
- полный текст по смысловым блокам и тайм-кодам;
- роль каждого блока: hook / tension / value / proof / reframe / CTA;
- ключевые опорные тезисы;
- эмоциональный триггер;
- триггер сохранения;
- триггер пересылки;
- конфликт в комментариях;
- визуальный формат A-roll/B-roll;
- монтажный ритм;
- CTA исходника;
- риски и упрощения.

## Этап 3. Clean-room адаптация
Создай рядом мой вариант:
- сохрани тему, контекст, смысловой конфликт, длительность, число блоков и эмоциональную функцию;
- измени предложения, метафоры, примеры, порядок аргументов и финальную формулу;
- не повторяй последовательность более 8 слов из исходника;
- не приписывай мне опыт, которого нет;
- не используй медицинские, финансовые или психологические гарантии;
- добавь практическую пользу: 3 вопроса, 3 шага или мини-чек-лист;
- закончи моим CTA и лид-магнитом.

## Этап 4. Раскадровка
Дай 9 кадров:
1. Hook Cover — 1,5 сек.
2. A-roll — хук.
3. B-roll — визуал проблемы.
4. A-roll — пункт 1.
5. B-roll — доказательство/метафора.
6. A-roll — пункт 2.
7. B-roll — усиление.
8. A-roll — афоризм.
9. CTA — 3 сек.

Для каждого кадра: длительность, план, действие, надпись, голос, переход.

## Формат результата
Верни JSON и интерактивный HTML. В карточке каждого Reel должны быть две колонки:
- «Конкурент: точный текст/реконструкция»;
- «Мой Reel: оригинальная версия теми же смыслами».

Добавь фильтры по теме, лайкам, дате, pinned, confidence и наличию transcript. Добавь кнопки копирования сценария и CSV/JSON-экспорт.
'''


def load_reels() -> list[dict[str, Any]]:
    payload = json.loads(SNAPSHOT.read_text(encoding="utf-8"))
    reels = []
    for item in payload["reels"]:
        code = item["shortCode"]
        meta = MANUAL[code]
        likes = item.get("likesCount")
        comments = item.get("commentsCount")
        ratio = round(comments / likes * 100, 2) if likes else None
        reels.append({
            "shortcode": code,
            "url": item["reelUrl"],
            "date": item.get("timestamp"),
            "duration": item.get("videoDuration"),
            "likes": likes,
            "comments": comments,
            "comment_like_ratio": ratio,
            "plays": item.get("playsCount"),
            "saves": item.get("savesCount"),
            "shares": item.get("sharesCount"),
            "pinned": bool(item.get("isPinned")),
            "transcript_status": "reconstructed",
            **meta,
        })
    reels.sort(key=lambda x: x.get("likes") or 0, reverse=True)
    return reels


def build_html(reels: list[dict[str, Any]]) -> str:
    data_json = json.dumps(reels, ensure_ascii=False).replace("</", "<\\/")
    prompt_json = json.dumps(MASTER_PROMPT, ensure_ascii=False).replace("</", "<\\/")
    themes = sorted({r["theme"] for r in reels})
    theme_options = "".join(f"<option value='{html.escape(t)}'>{html.escape(t)}</option>" for t in themes)
    css = r'''
:root{--bg:#2f2722;--panel:#43362f;--panel2:#514139;--cream:#f3ecdf;--ink:#28211d;--gold:#baa071;--gold2:#d5c29d;--muted:#9a897b;--line:#776458;--good:#78947f;--warn:#b28b58;--danger:#a6645d}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f2ede5;color:var(--ink);font:15px/1.6 Inter,Arial,sans-serif}.hero{min-height:78vh;padding:clamp(32px,7vw,100px);background:linear-gradient(135deg,#2c2521,#493a32 68%,#6a5547);color:var(--cream);display:flex;flex-direction:column;justify-content:center;border-left:7px solid var(--gold)}.eyebrow{color:var(--gold2);font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.hero h1{max-width:1050px;margin:14px 0;font:400 clamp(45px,7vw,92px)/.98 Georgia,serif;letter-spacing:-.035em}.hero p{max-width:850px;color:#d9cfc2;font-size:19px}.kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:30px;max-width:1050px}.kpi{padding:14px;border:1px solid #7c685b;background:rgba(255,255,255,.04)}.kpi b{display:block;color:white;font:400 27px Georgia,serif}.kpi span{font-size:11px;color:#cbbdaf}.audit{padding:20px 0;background:#3a302a;color:#e8dfd3;border-top:1px solid #604f44;border-bottom:1px solid #604f44}.audit-inner,.main{max-width:1380px;margin:auto;padding-left:22px;padding-right:22px}.audit strong{color:#dbc59b}.toolbar{position:sticky;top:0;z-index:10;display:grid;grid-template-columns:2fr repeat(3,1fr);gap:9px;padding:16px 0;background:rgba(242,237,229,.95);backdrop-filter:blur(12px)}input,select{width:100%;padding:12px 13px;border:1px solid #cfc1b2;background:#fffaf2;color:var(--ink);font:inherit}.count{margin:12px 0 24px;color:#75675d}.cards{display:grid;gap:18px}.reel{background:#fffaf3;border:1px solid #d7c9b9;box-shadow:0 12px 32px rgba(47,39,34,.08)}.reel-head{display:grid;grid-template-columns:1fr auto;gap:18px;padding:23px 25px;background:linear-gradient(110deg,var(--panel),var(--panel2));color:var(--cream)}.reel h2{margin:4px 0;font:400 30px Georgia,serif}.reel-head a{color:#f0dcc0}.badges{display:flex;gap:7px;flex-wrap:wrap}.badge{padding:4px 8px;border:1px solid #8d7667;color:#dfd1c2;font-size:11px}.badge.pin{background:#7b6348}.badge.medium{background:#6f765f}.badge.low{background:#805e54}.metrics{display:grid;grid-template-columns:repeat(6,minmax(80px,1fr));gap:1px;background:#d7c9b9;border-bottom:1px solid #d7c9b9}.metric{padding:12px 15px;background:#f7f0e7}.metric b{display:block;font:400 21px Georgia,serif}.metric span{font-size:10px;color:#7d6e62;text-transform:uppercase;letter-spacing:.08em}.body{padding:25px}.warning{padding:14px 17px;background:#f3e6d4;border-left:4px solid var(--warn);margin-bottom:18px}.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.col{padding:20px;border:1px solid #d9ccbe}.col.source{background:#eee5d9}.col.adapt{background:#f8f4ed}.col h3{margin:0 0 15px;font:400 25px Georgia,serif}.label{color:#8b735d;font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.hook{margin:10px 0 17px;padding:16px;border-left:3px solid var(--gold);background:#fffaf2;font:600 17px Georgia,serif}.timeline{display:grid;gap:8px}.segment{display:grid;grid-template-columns:70px 90px 1fr;gap:10px;padding:9px 0;border-bottom:1px solid #ded2c4}.segment time{color:#8b735d;font-weight:bold}.segment em{font-style:normal;color:#79695d;font-size:12px}.pillars{display:flex;gap:7px;flex-wrap:wrap;margin:14px 0}.pillar{padding:6px 9px;background:#e8ddd0;font-size:12px}.cta{padding:15px;margin-top:15px;background:#3c302a;color:#f4e9d9}.actions{display:flex;gap:9px;flex-wrap:wrap;margin:15px 0}button,.download{cursor:pointer;padding:9px 12px;border:1px solid #876e5c;background:#473831;color:#fff;text-decoration:none;font:inherit}.story-title{margin:30px 0 12px;font:400 26px Georgia,serif}.storyboard{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;background:#2f2722;padding:4px}.shot{min-height:190px;padding:12px;background:#4d3d35;color:white;display:flex;flex-direction:column}.shot:nth-child(3n),.shot:nth-child(5),.shot:nth-child(7){background:#322b27}.shot-top{display:flex;justify-content:space-between;font-size:10px;font-weight:bold}.shot-visual{margin-top:28px;color:var(--gold2);font:400 16px Georgia,serif}.shot-overlay{margin-top:auto;font-size:13px}.prompt{margin:60px 0;background:#302823;color:#eee4d7;padding:28px}.prompt h2{font:400 38px Georgia,serif}.prompt pre{white-space:pre-wrap;max-height:600px;overflow:auto;background:#211c19;padding:20px;color:#e9dfd3}.footer{padding:35px;color:#75675d;text-align:center}.hidden{display:none!important}@media(max-width:900px){.kpis{grid-template-columns:repeat(2,1fr)}.toolbar{grid-template-columns:1fr 1fr}.columns{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(3,1fr)}.storyboard{grid-template-columns:1fr}.shot{min-height:160px}}@media(max-width:540px){.toolbar{grid-template-columns:1fr}.hero h1{font-size:44px}.metrics{grid-template-columns:repeat(2,1fr)}.segment{grid-template-columns:60px 1fr}.segment em{display:none}.reel-head{grid-template-columns:1fr}}
'''
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Все доступные Reels @bartsevmatvei — интерактивная библиотека</title><style>{css}</style></head><body>
<header class="hero"><div class="eyebrow">COMPETITOR REELS LIBRARY · SOURCE VS CLEAN-ROOM</div><h1>Все доступные Reels Матвея Барцева</h1><p>Статистика, смысловая реконструкция, хук, CTA, опорные элементы, тайм-коды и оригинальный сценарий рядом. Получено 12 публично доступных Reels на срезе 16.08.2026.</p><div class="kpis"><div class="kpi"><b>12</b><span>Reels распаковано</span></div><div class="kpi"><b>6</b><span>набрали 1K+ лайков</span></div><div class="kpi"><b>3</b><span>закреплённых хита</span></div><div class="kpi"><b>0</b><span>точных transcript</span></div><div class="kpi"><b>12</b><span>clean-room сценариев</span></div></div></header>
<div class="audit"><div class="audit-inner"><strong>Аудит данных:</strong> точные saves, shares и plays чужого профиля недоступны в публичном snapshot и показаны как «н/д». Текст конкурента — смысловая реконструкция по метаданным и комментариям, а не выдуманная дословная цитата. После подключения Apify agent эта страница может быть пересобрана с transcript и закрытыми метриками.</div></div>
<main class="main"><div class="toolbar"><input id="search" placeholder="Поиск по теме, shortcode или тексту"><select id="theme"><option value="">Все темы</option>{theme_options}</select><select id="likes"><option value="0">Любые лайки</option><option value="1000">1 000+</option><option value="5000">5 000+</option><option value="30000">30 000+</option></select><select id="sort"><option value="likes">Сначала по лайкам</option><option value="date">Сначала новые</option><option value="comments">Сначала по комментариям</option></select></div><div class="count" id="count"></div><div class="cards" id="cards"></div>
<section class="prompt"><div class="eyebrow">REUSABLE SYSTEM</div><h2>Унифицированный промт поиска и адаптации конкурентов</h2><p>Скопируйте, замените переменные и передайте агенту вместе со ссылкой на профиль.</p><div class="actions"><button onclick="copyPrompt()">Скопировать промт</button><a class="download" href="{RAW_BASE}/unified_competitor_reels_prompt.md" download>Скачать MD</a><a class="download" href="{RAW_BASE}/bartsevmatvei_all_reels.json" download>Скачать JSON</a></div><pre id="prompt"></pre></section></main><div class="footer">Срез 16.08.2026 · значения «н/д» не считаются нулём · адаптации сохраняют механику, но не копируют длинные формулировки</div>
<script type="application/json" id="dataset">{data_json}</script><script type="application/json" id="promptData">{prompt_json}</script><script>
const DATA=JSON.parse(document.getElementById('dataset').textContent);const PROMPT=JSON.parse(document.getElementById('promptData').textContent);document.getElementById('prompt').textContent=PROMPT;
const fmt=n=>n==null?'н/д':new Intl.NumberFormat('ru-RU').format(n);const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[m]));
function timeline(items){{return `<div class="timeline">${{items.map(x=>`<div class="segment"><time>${{esc(x.time)}}</time><em>${{esc(x.role)}}</em><span>${{esc(x.text)}}</span></div>`).join('')}}</div>`}}
function storyboard(items){{return `<div class="storyboard">${{items.map(x=>`<div class="shot"><div class="shot-top"><span>${{x.n}}/9 ${{esc(x.kind)}}</span><span>${{esc(x.duration)}}</span></div><div class="shot-visual">${{esc(x.visual)}}</div><div class="shot-overlay">${{esc(x.overlay)}}</div></div>`).join('')}}</div>`}}
function card(r){{const script=r.adapt_script.map(x=>x.text).join('\\n');return `<article class="reel" data-theme="${{esc(r.theme)}}" data-likes="${{r.likes||0}}" data-date="${{esc(r.date)}}" data-comments="${{r.comments||0}}"><header class="reel-head"><div><div class="badges">${{r.pinned?'<span class="badge pin">PINNED</span>':''}}<span class="badge ${{r.confidence}}">CONFIDENCE: ${{r.confidence.toUpperCase()}}</span><span class="badge">${{esc(r.theme)}}</span></div><h2>${{esc(r.topic)}}</h2><a href="${{esc(r.url)}}" target="_blank">${{esc(r.shortcode)}} ↗</a></div><div>${{esc((r.duration||'н/д')+' сек')}}</div></header><div class="metrics"><div class="metric"><b>${{fmt(r.likes)}}</b><span>Лайки</span></div><div class="metric"><b>${{fmt(r.comments)}}</b><span>Комментарии</span></div><div class="metric"><b>${{fmt(r.comment_like_ratio)}}%</b><span>Комм./лайки</span></div><div class="metric"><b>${{fmt(r.plays)}}</b><span>Просмотры</span></div><div class="metric"><b>${{fmt(r.saves)}}</b><span>Сохранения</span></div><div class="metric"><b>${{fmt(r.shares)}}</b><span>Пересылки</span></div></div><div class="body"><div class="warning">Исходный текст: <b>смысловая реконструкция</b>, не дословная расшифровка. Уверенность: ${{esc(r.confidence)}}.</div><div class="columns"><section class="col source"><div class="label">Конкурент · структура исходника</div><h3>Что он говорит</h3><div class="hook">${{esc(r.source_hook)}}</div><p>${{esc(r.source_text)}}</p><h4>Тайм-коды и функции</h4>${{timeline(r.source_structure)}}<h4>Опорные элементы</h4><div class="pillars">${{r.pillars.map(p=>`<span class="pillar">${{esc(p)}}</span>`).join('')}}</div><h4>CTA исходника</h4><p>${{esc(r.source_cta)}}</p></section><section class="col adapt"><div class="label">Мой Reel · те же смыслы другими словами</div><h3>${{esc(r.adapt_title)}}</h3><div class="hook">${{esc(r.adapt_hook)}}</div>${{timeline(r.adapt_script)}}<div class="cta">${{esc(r.adapt_cta)}}</div><div class="actions"><button onclick='copyScript(${{JSON.stringify(script)}})'>Скопировать мой текст</button></div></section></div><h3 class="story-title">Раскадровка 9 кадров</h3>${{storyboard(r.storyboard)}}</div></article>`}}
function render(){{let items=[...DATA];const q=document.getElementById('search').value.toLowerCase();const theme=document.getElementById('theme').value;const min=+document.getElementById('likes').value;const sort=document.getElementById('sort').value;items=items.filter(r=>(!theme||r.theme===theme)&&(r.likes||0)>=min&&(!q||JSON.stringify(r).toLowerCase().includes(q)));items.sort((a,b)=>sort==='date'?String(b.date).localeCompare(String(a.date)):sort==='comments'?(b.comments||0)-(a.comments||0):(b.likes||0)-(a.likes||0));document.getElementById('count').textContent=`Показано: ${{items.length}} из ${{DATA.length}}`;document.getElementById('cards').innerHTML=items.map(card).join('')}}
['search','theme','likes','sort'].forEach(id=>document.getElementById(id).addEventListener(id==='search'?'input':'change',render));function copyScript(t){{navigator.clipboard.writeText(t)}}function copyPrompt(){{navigator.clipboard.writeText(PROMPT)}}render();
</script></body></html>'''


def build_markdown(reels: list[dict[str, Any]]) -> str:
    lines = ["# Все доступные Reels @bartsevmatvei", "", "> Важно: исходные тексты являются смысловой реконструкцией, а не дословной расшифровкой.", ""]
    for i, r in enumerate(reels, 1):
        lines += [f"## {i}. {r['shortcode']} — {r['topic']}", "", f"- URL: {r['url']}", f"- Лайки: {r['likes']}; комментарии: {r['comments']}; длительность: {r['duration']} сек.", f"- Confidence: {r['confidence']}", "", "### Конкурент — реконструкция", "", f"**Хук:** {r['source_hook']}", "", r['source_text'], ""]
        for s in r["source_structure"]: lines.append(f"- **{s['time']} · {s['role']}:** {s['text']}")
        lines += ["", "### Мой Reel", "", f"**{r['adapt_title']}**", "", f"**Хук:** {r['adapt_hook']}", ""]
        for s in r["adapt_script"]: lines.append(f"- **{s['time']} · {s['role']}:** {s['text']}")
        lines += ["", f"> {r['adapt_cta']}", "", "---", ""]
    return "\n".join(lines)


def main() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    reels = load_reels()
    (OUT / "bartsevmatvei_all_reels.json").write_text(json.dumps(reels, ensure_ascii=False, indent=2), encoding="utf-8")
    (OUT / "unified_competitor_reels_prompt.md").write_text(MASTER_PROMPT, encoding="utf-8")
    (OUT / "all_reels_source_vs_adaptation.md").write_text(build_markdown(reels), encoding="utf-8")
    (OUT / "index.html").write_text(build_html(reels), encoding="utf-8")
    archive = ROOT / "deliverables" / "bartsev_all_reels_library.zip"
    if archive.exists(): archive.unlink()
    subprocess.run(["zip", "-r", "-9", str(archive), OUT.name], cwd=OUT.parent, check=True, stdout=subprocess.DEVNULL)
    print(json.dumps({"reels": len(reels), "html": str(OUT/'index.html'), "archive": str(archive), "bytes": archive.stat().st_size}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
